    layout: sub(L("Layout", "Layout", "Dise\xF1o"), ic("dashboard"), () => layoutMenu(env, ctx, "change"), "layout"),
    background: sub(L("Background", "Plano de fundo", "Fondo"), ic("wallpaper"), () => backgroundMenu(env, ctx), "background"),
